"""React pages (generated by `lila react init`).

Pages mode: react_render(request, "<Component>", props, title=..., jsonld=...)
renders resources/react/pages/<Component>.jsx with server props and SEO.
SPA mode: router.spa("/app", meta={...}) serves a React Router app.

desktop=False keeps a route out of the desktop build (`lila desktop build`);
desktop="only" keeps it out of the website.
"""

from lila.core.react import react_render
from lila.core.request import Request
from lila.core.routing import Router
from lila.core.sse import Channel
from lila.core.websocket import WebSocketHub

router = Router()


@router.get("/react")
async def react_home(request: Request):
    return react_render(
        request,
        "Home",
        {"framework": "Lila", "features": ["Server props", "Vite HMR", "SEO from Python", "Desktop builds"]},
        title="React",
        description="Lila pages rendered with React and Vite.",
        canonical=True,
        jsonld={"@context": "https://schema.org", "@type": "WebSite", "name": "Lila React"},
        meta={"theme-color": "#1a73e8"},
    )


@router.get("/react/about")
async def react_about(request: Request):
    return react_render(
        request,
        "About",
        {"version": __import__("lila").__version__},
        title="About",
        description="About this Lila + React app.",
        jsonld={"@context": "https://schema.org", "@type": "AboutPage", "name": "About"},
    )


# Web-only: payments never ship in the desktop app.
@router.get("/react/checkout", desktop=False)
async def react_checkout(request: Request):
    return react_render(request, "Checkout", {"plans": ["Basic", "Pro"]}, title="Checkout", robots="noindex")


@router.post("/react/checkout", desktop=False, csrf=True)
async def react_checkout_post(request: Request):
    data = await request.json()
    return {"success": True, "message": f"Plan {data.get('plan', '?')} selected (demo)."}


# Real-time demo for the SPA "Live" page (@lila/realtime: useSSE / useWebSocket).
demo_events = Channel("lila-demo")
demo_hub = WebSocketHub()


@router.get("/app-events", openapi=False)
async def demo_stream(request: Request):
    return demo_events.stream(request)


@router.post("/app-events", csrf=True, openapi=False)
async def demo_publish(request: Request):
    data = await request.json()
    await demo_events.publish({"text": str(data.get("text", ""))[:200]}, event="demo:message")
    return {"success": True}


@demo_hub.on("chat:message")
async def demo_chat(websocket, data):
    text = str((data or {}).get("text", ""))[:200] if isinstance(data, dict) else ""
    if text:
        await demo_hub.broadcast("chat:message", {"text": text}, room="general")


router.ws_hub("/ws/demo", demo_hub)


# SPA with React Router under /app; meta per client route (dict or callable).
router.spa(
    "/app",
    meta={
        "*": {"title": "App", "description": "Lila SPA"},
        "/": {"title": "SPA Home", "jsonld": {"@context": "https://schema.org", "@type": "WebApplication", "name": "Lila SPA"}},
        "users": {"title": "Users"},
        "users/:id": lambda request, params: {"title": f"User {params['id']}", "robots": "noindex"},
        "account": {"title": "Account", "robots": "noindex"},
        "live": {"title": "Live"},
        "billing": {"title": "Billing"},
    },
)
